(function(){'use strict';
const E=globalThis.AurumEngine,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(v,n=2)=>Number.isFinite(v)?v.toFixed(n):'—',pct=v=>Number.isFinite(v)?(v*100).toFixed(2)+'%':'—';
const labels={overview:'把黄金研究，落到可检验的信号。',factors:'从量价直觉，走向因子证据。',chan:'把价格结构，放回它的确认时点。',news:'让每条舆情，都有可追溯的出处。',audit:'研究判断，也需要一份变更记录。',data:'先明确来路，再开始计算。'};
let dataset=[],bars=[],news=[],provenance={},newsMeta={source:'尚未导入',synthetic:false},result=null,cutoff=0,importMode='prices';
let assertions=[],audits=[];try{assertions=JSON.parse(localStorage.getItem('aurum-assertions-v2')||'[]');audits=JSON.parse(localStorage.getItem('aurum-audits-v2')||'[]');if(!Array.isArray(assertions)||!Array.isArray(audits))throw Error();}catch{assertions=[];audits=[];}
function persist(){try{localStorage.setItem('aurum-assertions-v2',JSON.stringify(assertions));localStorage.setItem('aurum-audits-v2',JSON.stringify(audits.slice(-100)));}catch{toast('当前浏览器未允许本地存储；本次记录仅在页面会话保留。');}}
function log(action,detail){audits.push({at:new Date().toISOString(),action,detail});persist();renderAudit();}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500);}
function tab(name){if(!labels[name])name='overview';document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===name));document.querySelectorAll('nav button').forEach(el=>{el.classList.toggle('active',el.dataset.tab===name);el.setAttribute('aria-current',el.dataset.tab===name?'page':'false');});$('page-title').textContent=labels[name];history.replaceState(null,'','#'+name);}
document.querySelectorAll('[data-tab],[data-jump]').forEach(el=>el.addEventListener('click',()=>tab(el.dataset.tab||el.dataset.jump)));
function attach(arr,p){Object.defineProperty(arr,'provenance',{value:p,configurable:true,enumerable:false});return arr;}
function setData(data,source,sourceNews=[],sourceNewsMeta=null){dataset=data;provenance=source||data.provenance||{};news=sourceNews;newsMeta=sourceNewsMeta||{source:news.length?'样例新闻（合成）':'尚未导入真实舆情',synthetic:!!provenance.synthetic};let symbols=[...new Set(dataset.map(b=>b.symbol))];$('symbol-select').innerHTML=symbols.map(s=>`<option>${esc(s)}</option>`).join('');selectSymbol(false);log('载入数据',`${provenance.source||'未声明'}；${dataset.length}行；${provenance.synthetic?'合成数据':'用户/公开来源声明'}`);}
function selectSymbol(withLog=true){bars=attach(dataset.filter(b=>b.symbol===$('symbol-select').value),provenance);cutoff=bars.length-1;$('history').max=String(cutoff);$('history').value=String(cutoff);recompute(false);if(withLog)log('切换标的',$('symbol-select').value);}
function options(){let fee=Number($('fee').value),slip=Number($('slippage').value);if(!Number.isFinite(fee)||!Number.isFinite(slip)||fee<0||slip<0||fee>100||slip>100)throw Error('手续费与滑点应为0至100 bps的有限数值');return $('factor-select').value==='auto'?{factor:'auto',feeBps:fee,slippageBps:slip}:{factors:$('factor-select').value.split('+'),feeBps:fee,slippageBps:slip};}
function recompute(withLog=true){try{result=E.analyze(bars,news,options());render();if(withLog)log('完成因子与回测计算',`因子 ${result.selectedFactors.join(',')}；测试起点 ${result.split.date}；单边成本 ${result.backtest.costPerSide*10000}bps`);return true;}catch(e){toast(e.message);return false;}}
function render(){let m=result.backtest.metrics;const last=bars.at(-1),prev=bars.at(-2),change=last.close/prev.close-1;$('notice').className='notice'+(provenance.synthetic?'':' real');$('notice').textContent=provenance.synthetic?'合成样例正在运行 · 价格、新闻均为教学数据，不能作为真实业绩；iFinD数据需授权导出后导入。':`${provenance.source||'用户数据'} · 真实来源声明尚未独立核验；不是实时行情。${news.length?' 舆情来源另行记录。':' 尚未导入真实舆情，不展示虚构新闻。'}`;
$('metrics').innerHTML=[['参考收盘',num(last.close,3),last.symbol+' · '+last.date],['单期价格变化',pct(change),'最后两个行情日期之间的变化'],['样本外研究收益',pct(m.totalReturn),'含费用 · '+m.intervals+'个收益区间'],['研究组合最大回撤',pct(m.maxDrawdown),'测试期 · 非实盘账户']].map(([l,v,n])=>`<div class="metric"><small>${l}</small><strong>${v}</strong><p>${esc(n)}</p></div>`).join('');
$('symbol-tag').textContent=last.symbol+' · 日频';$('factor-table').innerHTML=result.factors.map(f=>`<tr tabindex="0" data-factor="${esc(f.key)}" title="选择此因子并重新计算"><td>${esc(f.label)}</td><td>${num(f.trainIC,4)}</td><td>${num(f.testIC,4)}</td><td>${f.direction===1?'正向':'反向'}</td><td>${f.testSamples}</td></tr>`).join('');$('factor-table').querySelectorAll('tr').forEach(row=>{let choose=()=>{$('factor-select').value=row.dataset.factor;recompute();};row.onclick=choose;row.onkeydown=e=>{if(e.key==='Enter')choose();};});
$('factor-chart').innerHTML=factorChart();$('nav-chart').innerHTML=navChart();renderStructure();renderNews();renderProvenance();$('steps').innerHTML=['数据校验','因子计算','训练定方向','样本外回测','证据与报告'].map((t,i)=>`<span><i>✓</i>${t}</span>${i<4?'<em></em>':''}`).join('');}
function svg(content,w=960,h=340,label='研究图表'){return`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg"><style>text{font-family:system-ui,Microsoft YaHei,sans-serif;fill:#8a959d;font-size:10px}</style>${content}</svg>`;}
function renderStructure(){let prefix=bars.slice(0,cutoff+1),structure=E.chan(prefix);let graphic=candleChart(prefix,structure,$('overlay').checked);$('price-chart').innerHTML=graphic;$('chan-chart').innerHTML=candleChart(prefix,structure,true);$('history-date').textContent=prefix.at(-1).date;$('structure-status').textContent=`截止所选日期共 ${prefix.length} 根原始K线，图中展示最后${Math.min(prefix.length,100)}根；确认分型 ${structure.fractals.length} 个。`;
$('snapshot').innerHTML=[['数据窗口',bars[0].date+' / '+bars.at(-1).date],['已确认分型',structure.fractals.length+' 个'],['简化笔 / 中枢',structure.strokes.length+' / '+structure.centers.length],['背驰候选',structure.divergences.length+' 个 · 启发式'],['研究方向',result.selectedFactors.join(' + ')],['测试起点',result.split.date]].map(([a,b])=>`<div class="snap-row"><span>${a}</span><b>${esc(b)}</b></div>`).join('');
$('chan-counts').innerHTML=[['合并后K线',structure.merged.length],['确认分型',structure.fractals.length],['交替笔',structure.strokes.length],['中枢交集',structure.centers.length]].map(([a,b])=>`<div>${a}<strong>${b}</strong></div>`).join('');
let events=[...structure.fractals.map(f=>({label:f.type==='top'?'顶分型':'底分型',date:f.date,confirm:f.confirmedAt,info:num(f.price,3)})),...structure.divergences.map(d=>({label:d.type,date:d.date,confirm:d.confirmedAt,info:'MACD面积减弱 / 候选'}))].sort((a,b)=>b.confirm.localeCompare(a.confirm)).slice(0,22);
$('chan-events').innerHTML=events.length?events.map(e=>`<tr><td>${esc(e.label)}</td><td>${esc(e.date)}</td><td>${esc(e.confirm)}</td><td>${esc(e.info)}</td></tr>`).join(''):'<tr><td colspan="4">当前截止日尚未满足确认条件。</td></tr>';}
function candleChart(arr,c,overlay){let start=Math.max(0,arr.length-100),a=arr.slice(start),left=62,right=930,top=25,bottom=242,vbottom=306,lo=Math.min(...a.map(b=>b.low)),hi=Math.max(...a.map(b=>b.high)),span=hi-lo||1;lo-=span*.08;hi+=span*.08;let x=i=>left+(i+.5)*(right-left)/a.length,y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top),vmax=Math.max(...a.map(b=>b.volume)),step=(right-left)/a.length,width=Math.max(1,step*.6),map=Object.fromEntries(a.map((b,i)=>[b.date,i]));let out='';
for(let i=0;i<5;i++){let yy=top+i*(bottom-top)/4;out+=`<line x1="${left}" y1="${yy}" x2="${right}" y2="${yy}" stroke="#e9e7df"/><text x="5" y="${yy+4}">${num(hi-i*(hi-lo)/4,3)}</text>`;}
if(overlay){for(let center of c.centers){let end=map[center.endDate],begin=map[center.startDate];if(end===undefined&&center.endDate<a[0].date)continue;begin=begin??0;end=end??a.length-1;out+=`<rect x="${x(begin)-step/2}" y="${y(center.high)}" width="${Math.max(step,x(end)-x(begin)+step)}" height="${Math.max(1,y(center.low)-y(center.high))}" fill="#b78240" fill-opacity=".07" stroke="#b78240" stroke-opacity=".35" stroke-dasharray="4 3"/>`;}}
a.forEach((b,i)=>{let color=b.close>=b.open?'#b78240':'#397e78',xx=x(i);out+=`<g><title>${esc(b.date)} O ${num(b.open,3)} H ${num(b.high,3)} L ${num(b.low,3)} C ${num(b.close,3)} V ${b.volume}</title><line x1="${xx}" x2="${xx}" y1="${y(b.high)}" y2="${y(b.low)}" stroke="${color}"/><rect x="${xx-width/2}" y="${y(Math.max(b.open,b.close))}" width="${width}" height="${Math.max(1,Math.abs(y(b.open)-y(b.close)))}" fill="${color}"/><rect x="${xx-width/2}" y="${vbottom-b.volume/vmax*40}" width="${width}" height="${b.volume/vmax*40}" fill="${color}" opacity=".38"/></g>`;});
if(overlay){for(let s of c.strokes){if(map[s.startDate]!==undefined&&map[s.endDate]!==undefined)out+=`<line x1="${x(map[s.startDate])}" y1="${y(s.start.price)}" x2="${x(map[s.endDate])}" y2="${y(s.end.price)}" stroke="#a26b3d" stroke-width="1.8"/>`;}for(let f of c.fractals){if(map[f.date]!==undefined)out+=`<circle cx="${x(map[f.date])}" cy="${y(f.price)}" r="3" fill="${f.type==='top'?'#b78240':'#397e78'}"><title>${esc(f.type)} 发生 ${f.date}，确认 ${f.confirmedAt}</title></circle>`;}}
for(let i of [0,Math.floor(a.length/3),Math.floor(a.length*2/3),a.length-1])out+=`<text x="${x(i)}" y="327" text-anchor="middle">${a[i].date}</text>`;out+='<text x="5" y="282">VOL</text>';return svg(out,960,340,'行情K线、成交量及简化缠论结构');}
function navChart(){let rows=result.backtest.equity;if(!rows.length)return'<p class="empty">暂无可计算的测试期。</p>';let vals=rows.flatMap(r=>[r.nav,r.benchmark]).concat(1),min=Math.min(...vals),max=Math.max(...vals),span=max-min||.01,x=i=>60+i*870/Math.max(1,rows.length-1),y=v=>230-(v-min)/span*195;let o='';for(let i=0;i<4;i++){let v=min+i*span/3,yy=y(v);o+=`<line x1="60" y1="${yy}" x2="930" y2="${yy}" stroke="#e9e7df"/><text x="10" y="${yy+4}">${num(v,3)}</text>`;}for(let [key,color]of[['benchmark','#aeb8bb'],['nav','#397e78']])o+=`<polyline points="${rows.map((r,i)=>x(i)+','+y(r[key])).join(' ')}" fill="none" stroke="${color}" stroke-width="2.1"/>`;o+='<text x="65" y="18" fill="#397e78">策略净值</text><text x="145" y="18">同标的买入持有</text>';
let dd=rows.map(r=>r.drawdown),dmin=Math.min(...dd,-.01);o+=`<polygon points="60,265 ${rows.map((r,i)=>x(i)+','+(265+r.drawdown/dmin*40)).join(' ')} 930,265" fill="#b78240" opacity=".18"/><text x="8" y="285">回撤</text><text x="60" y="330">${rows[0].date}</text><text x="930" y="330" text-anchor="end">${rows.at(-1).date}</text>`;return svg(o,960,345,'样本外净值与回撤');}
function factorChart(){let fs=result.factors,center=530,scale=320,h=fs.length*32+45,o='<line x1="530" y1="10" x2="530" y2="'+(h-25)+'" stroke="#d3d8d4"/>';fs.forEach((f,i)=>{let yy=20+i*32;o+=`<text x="12" y="${yy+10}" style="font-size:12px">${esc(f.label)}</text>`;for(let [key,col,offset]of[['trainIC','#b78240',0],['testIC','#397e78',10]]){let v=f[key];if(v!==null)o+=`<rect x="${center+Math.min(0,v)*scale}" y="${yy+offset}" width="${Math.abs(v)*scale}" height="8" fill="${col}"/>`;}o+=`<text x="880" y="${yy+10}" text-anchor="end">${num(f.testIC,3)}</text>`;});o+=`<text x="200" y="${h-4}">−1</text><text x="530" y="${h-4}">0</text><text x="840" y="${h-4}">+1</text><text x="12" y="${h-4}">铜：训练 / 绿：测试</text>`;return svg(o,960,h,'训练和测试时间序列Rank IC');}
function renderNews(){let daily=result.newsDaily,nonzero=daily.filter(d=>d.count);$('news-status').textContent=`${newsMeta.synthetic?'合成新闻样例':'舆情来源声明'}：${newsMeta.source}；去重后 ${news.length} 条，${nonzero.length} 个日期对齐到行情。无新闻观测日保持缺失，不据此声称全年完整覆盖。`;
if(!news.length){$('sentiment-chart').innerHTML='<div class="empty">尚未导入真实舆情。导入包含发布时间、标题、来源的CSV后，研究台会保守地滞后一日对齐。<br>不会用合成新闻填充真实行情。</div>';$('news-list').innerHTML='';return;}
let n=daily.length,x=i=>60+i*870/Math.max(1,n-1),o='<line x1="60" y1="130" x2="930" y2="130" stroke="#e6e4dc"/>';daily.forEach((d,i)=>{if(d.count)o+=`<rect x="${x(i)-2}" y="${d.sentiment>=0?130-d.sentiment*90:130}" width="4" height="${Math.max(1,Math.abs(d.sentiment)*90)}" fill="${d.sentiment>=0?'#397e78':'#bc6b58'}"><title>${d.date}: ${d.count}条，净分${num(d.sentiment,3)}</title></rect>`;});o+='<text x="15" y="45">+1</text><text x="15" y="135">0</text><text x="15" y="225">−1</text>';o+=`<text x="60" y="255">${daily[0].date}</text><text x="930" y="255" text-anchor="end">${daily.at(-1).date}</text>`;$('sentiment-chart').innerHTML=svg(o,960,270,'新闻净分按可得日期对齐');
let items=daily.flatMap(d=>d.items.map(item=>({...item,aligned:d.date}))).reverse().slice(0,30);$('news-list').innerHTML=items.map(n=>`<div class="news-item"><span class="source">${esc(n.source)}${n.url?` · <a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">原文 ↗</a>`:''}</span><span class="score">${num(n.sentiment,2)}</span><h3>${esc(n.title)}</h3><p>发表：${esc(n.published_at)}　可用：${esc(n.aligned)}</p><p>评分方法：${esc(n.scoring)}${newsMeta.synthetic?' · 合成样例':''}</p></div>`).join('');}
function renderProvenance(){$('provenance').innerHTML='<dl>'+[['来源声明',provenance.source||'未声明'],['数据性质',provenance.synthetic?'合成数据':'真实来源声明 / 未独立核验'],['文件名',provenance.filename||'随站点样例'],['当前标的',bars[0].symbol],['日期范围',bars[0].date+' 至 '+bars.at(-1).date],['记录数',bars.length+' 条（全部文件 '+dataset.length+' 条）'],['价格口径',provenance.priceBasis||'未声明'],['成交量单位',provenance.volumeUnit||'未声明']].map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join('')+'</dl>'+(result.warnings.length?'<div class="rule-note">'+result.warnings.map(esc).join('<br>')+'</div>':'');}
function renderAudit(){$('assertions').innerHTML=assertions.length?assertions.map(a=>`<div class="assertion"><span class="status-pill">${esc({proposed:'待检验',active:'研究中',falsified:'已证伪'}[a.status])}</span><strong>${esc(a.title)}</strong><p>${esc(a.evidence)}</p><select aria-label="断言状态" data-assert="${esc(a.id)}"><option value="proposed" ${a.status==='proposed'?'selected':''}>待检验</option><option value="active" ${a.status==='active'?'selected':''}>研究中</option><option value="falsified" ${a.status==='falsified'?'selected':''}>已证伪（人工确认）</option></select></div>`).join(''):'<p class="empty">尚无研究断言。先写下你准备如何验证或证伪。</p>';$('assertions').querySelectorAll('select').forEach(el=>el.onchange=()=>{let a=assertions.find(x=>x.id===el.dataset.assert);a.status=el.value;log('断言状态更新',a.title+' → '+a.status);});$('audit-list').innerHTML=audits.slice(-20).reverse().map(a=>`<div class="audit-item"><time>${esc(a.at)}</time><b>${esc(a.action)}</b><div>${esc(a.detail)}</div></div>`).join('')||'<p class="empty">尚无操作记录。</p>';}
function download(name,text,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成下载文件：'+name);}
function csvText(rows){if(!rows.length)return'date,signalDate,side,price,notional,cost,targetWeight\n';let fields=Object.keys(rows[0]);let quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return'\uFEFF'+[fields,...rows.map(r=>fields.map(f=>r[f]))].map(row=>row.map(quote).join(',')).join('\r\n');}
function openImport(mode){importMode=mode;$('import-title').textContent=mode==='prices'?'导入行情 CSV':'导入新闻 CSV';$('price-import-options').hidden=mode!=='prices';$('import-text').placeholder=mode==='prices'?'date,symbol,open,high,low,close,volume,amount':'published_at,title,source,sentiment';$('import-error').textContent='';$('import-file').value='';$('import-text').value='';$('source-name').value='';$('data-nature').value='';$('import-dialog').showModal();}
$('import-form').onsubmit=async e=>{e.preventDefault();try{let file=$('import-file').files[0],text=$('import-text').value;if(file){let buffer=await file.arrayBuffer();text=new TextDecoder('utf-8',{fatal:true}).decode(buffer);}if(!text.trim())throw Error('请选取CSV文件或粘贴内容');let source=$('source-name').value.trim();if(!source||!$('data-nature').value)throw Error('请填写来源并选择数据性质');let synthetic=$('data-nature').value==='synthetic';if(importMode==='prices'){let p={source,synthetic,filename:file?.name||'粘贴CSV',priceBasis:$('price-basis').value.trim()||'未声明，需核对',volumeUnit:$('volume-unit').value.trim()||'未声明，需核对'},data=E.parsePrices(text,p);let symbols=[...new Set(data.map(b=>b.symbol))];for(let symbol of symbols)if(data.filter(b=>b.symbol===symbol).length<65)throw Error(symbol+' 少于65条记录，请增加历史数据');setData(data,p,[],{source:'新行情尚未导入舆情',synthetic:false});}else{news=E.parseNews(text);newsMeta={source,synthetic};for(let n of news)n.source=n.source==='用户导入'?source:n.source;recompute(false);log('导入舆情',source+'；'+news.length+'条；'+(synthetic?'合成新闻':'真实来源声明'));} $('import-dialog').close();toast('数据校验与本地计算完成');}catch(e){$('import-error').textContent=e instanceof TypeError?'读取失败；请另存为UTF-8 CSV再导入。':e.message;}};
$('close-dialog').onclick=()=>$('import-dialog').close();$('import-btn').onclick=$('data-import-btn').onclick=()=>openImport('prices');$('news-import-btn').onclick=()=>openImport('news');$('overlay').onchange=renderStructure;$('history').oninput=e=>{cutoff=Number(e.target.value);renderStructure();};$('show-current').onclick=()=>{cutoff=bars.length-1;$('history').value=cutoff;renderStructure();};$('symbol-select').onchange=()=>{try{selectSymbol();}catch(e){toast(e.message);}};$('recompute').onclick=()=>recompute();
$('task-form').onsubmit=e=>{e.preventDefault();let task=$('task-input').value.trim();if(!recompute(false))return;let target=task.includes('缠论')||task.includes('图形')?'chan':task.includes('舆情')||task.includes('新闻')?'news':task.includes('因子')?'factors':'overview';tab(target);log('执行规则任务',task||'默认量价研究流程');toast('已执行确定性研究流程。任务文字用于选择模块，未调用LLM。');};
$('assert-form').onsubmit=e=>{e.preventDefault();assertions.push({id:'a'+Date.now(),title:$('assert-title').value.trim(),evidence:$('assert-evidence').value.trim(),status:'proposed',createdAt:new Date().toISOString()});log('登记研究断言',$('assert-title').value.trim());$('assert-form').reset();};
$('ledger-export').onclick=()=>{download('aurum-ledger.csv',csvText(result.backtest.ledger),'text/csv;charset=utf-8');log('导出账本',result.backtest.ledger.length+'条研究成交');};$('json-export').onclick=()=>{download('aurum-research.json',JSON.stringify({...result,newsMeta,options:options()},null,2),'application/json');log('导出研究JSON',provenance.source);};$('audit-export').onclick=()=>download('aurum-audit.json',JSON.stringify({assertions,audits},null,2),'application/json');
$('report-export').onclick=()=>{let html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Aurum研究报告</title><style>body{font:15px/1.8 system-ui;max-width:1000px;margin:50px auto;padding:20px;color:#1b3044}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}svg{width:100%}.notice{background:#f2eadb;padding:15px}</style><h1>Aurum 黄金因子研究报告</h1><p class="notice">'+esc($('notice').textContent)+'</p><p>导出时间：'+new Date().toISOString()+'</p><h2>数据来源</h2>'+$('provenance').innerHTML+'<h2>样本外净值</h2>'+navChart()+'<h2>因子检验</h2><table>'+$('factor-table').parentElement.innerHTML+'</table><h2>简化结构</h2>'+candleChart(bars.slice(0,cutoff+1),E.chan(bars.slice(0,cutoff+1)),true)+'<p>图形按所选截止日期计算，末端结构可修订，不用于当前回测。IC为时间序列相关；长仓/现金研究回放，t-1信号在t日收盘参考成交，费用单边'+result.backtest.costPerSide*10000+'bps。非实盘，不含交易限制和市场冲击。</p></html>';download('aurum-report.html',html,'text/html;charset=utf-8');log('导出独立报告',provenance.source);};
$('price-template').onclick=()=>download('price-template.csv','\uFEFFdate,symbol,open,high,low,close,volume,amount\r\n','text/csv;charset=utf-8');$('news-template').onclick=()=>download('news-template.csv','\uFEFFpublished_at,title,source,sentiment\r\n','text/csv;charset=utf-8');
$('factor-select').innerHTML=[['auto','训练期自动筛选（最多3因子）'],['mom5','5日动量'],['mom20','20日动量'],['reversal5','5日反转'],['vol20','20日低波动'],['volumeSurprise','量能异常'],['amihud','Amihud流动性近似'],['range','日内振幅'],['clv','收盘位置'],['sentiment','舆情净分'],['newsAttention','新闻关注度'],['mom20+sentiment','20日动量 + 舆情净分']].map(([a,b])=>`<option value="${a}">${b}</option>`).join('');$('factor-select').value='auto';
$('demo-btn').onclick=()=>{let d=E.makeDemo();setData(d.prices,d.provenance,d.news,{source:'确定性合成新闻样例',synthetic:true});toast('已切换为合成行情与合成新闻。');};
if(globalThis.AurumPublicSample){let pub=document.createElement('button');pub.className='button ghost';pub.id='public-btn';pub.textContent='载入公开黄金样例';pub.onclick=()=>{let d=globalThis.AurumPublicSample;setData(d.prices,d.provenance,d.news||[],d.newsProvenance||{source:'公开行情样例无配套新闻',synthetic:false});};$('demo-btn').after(pub);let d=globalThis.AurumPublicSample;setData(d.prices,d.provenance,d.news||[],d.newsProvenance||{source:'公开行情样例无配套新闻',synthetic:false});}else{let d=E.makeDemo();setData(d.prices,d.provenance,d.news,{source:'确定性合成新闻样例',synthetic:true});}
renderAudit();tab(location.hash.slice(1));
})();
